// Builds the exam blueprint: how questions map onto curriculum chapters,
// how marks are distributed, RBL levels used, and CO mapping.
// This MUST run before any question text is generated.

const examConfig = $input.first().json.examConfig;
const chapters = examConfig.curriculum.chapters;

const totalQuestions = examConfig.totalQuestions;
const marksPerQuestion = examConfig.marksPerQuestion;

// Distribute questions as evenly as possible across chapters, then across
// topics within each chapter (round-robin), so coverage is comparable
// across Set A / Set B.
const allTopics = [];
chapters.forEach(ch => {
  ch.topics.forEach(topic => {
    allTopics.push({ chapter: ch.chapter, topic });
  });
});

const distribution = [];
for (let i = 0; i < totalQuestions; i++) {
  const t = allTopics[i % allTopics.length];
  distribution.push({
    questionNumber: i + 1,
    chapter: t.chapter,
    topic: t.topic,
    marks: marksPerQuestion
  });
}

// Simple RBL (Revised Bloom's Level) spread: cycle through levels so the
// paper isn't all one difficulty tier.
const RBL_LEVELS = ['Remember', 'Understand', 'Apply', 'Analyze'];
distribution.forEach((d, idx) => {
  d.rbl = RBL_LEVELS[idx % RBL_LEVELS.length];
  // Course Outcome mapping - one CO per chapter, in order of first
  // appearance, so the same chapter always maps to the same CO.
});

const chapterOrder = [...new Set(distribution.map(d => d.chapter))];
const coMap = {};
chapterOrder.forEach((ch, idx) => { coMap[ch] = `CO${idx + 1}`; });
distribution.forEach(d => { d.courseOutcomes = [coMap[d.chapter]]; });

const blueprint = {
  totalQuestions,
  questionsToAnswer: examConfig.questionsToAnswer,
  marksPerQuestion,
  maximumMarks: examConfig.maximumMarks,
  chapterCoverage: chapterOrder,
  courseOutcomeMap: coMap,
  distribution
};

return [{ json: { examConfig, blueprint } }];

const examConfig = $input.first().json.examConfig;
const blueprint = $input.first().json.blueprint;

const distributionText = blueprint.distribution.map(d =>
  `Q${d.questionNumber}: Chapter "${d.chapter}" / Topic "${d.topic}", ` +
  `Marks: ${d.marks}, RBL: ${d.rbl}, CO: ${d.courseOutcomes.join(', ')}`
).join('\n');

const prompt = `You are generating exam questions for a school exam.

Class: ${examConfig.class}
Subject: ${examConfig.subject}
Exam Type: ${examConfig.examType}
Academic level: appropriate for Class ${examConfig.class} students.

Generate SET A of the question paper strictly following this blueprint
(one question per line item below, in the same order):

${distributionText}

Rules:
- Each question must match its assigned chapter and topic.
- Each question must be clear, answerable, and academically meaningful.
- Do NOT include answers, solutions, or answer-key information anywhere.
- Do NOT introduce topics outside the assigned chapter/topic.
- Do NOT duplicate any question within this set.

Return ONLY a JSON array (no prose, no markdown fences) where each item has
exactly this shape:
{
  "questionNumber": number,
  "question": "string",
  "marks": number,
  "rbl": "string",
  "courseOutcomes": ["string"],
  "chapter": "string",
  "topic": "string"
}`;

return [{ json: { examConfig, blueprint, prompt, setName: 'Set A' } }];

const prior = $('Build Prompt - Set A').first().json;
const aiResponse = $input.first().json;

function extractText(resp) {
  // Gemini generateContent response format
  if (resp && Array.isArray(resp.candidates) && resp.candidates.length > 0) {
    const candidate = resp.candidates[0];
    const parts = candidate && candidate.content && candidate.content.parts;
    if (Array.isArray(parts)) {
      const textPart = parts.find(p => typeof p.text === 'string');
      if (textPart) return textPart.text;
    }
  }
  // Legacy content-array response format (kept for backward compatibility)
  if (resp && Array.isArray(resp.content)) {
    const textBlock = resp.content.find(b => b.type === 'text');
    if (textBlock) return textBlock.text;
  }
  if (typeof resp === 'string') return resp;
  return JSON.stringify(resp);
}

function safeParseArray(text) {
  const cleaned = text.replace(/```json|```/g, '').trim();
  try {
    const parsed = JSON.parse(cleaned);
    return Array.isArray(parsed) ? parsed : null;
  } catch (e) {
    return null;
  }
}

const raw = extractText(aiResponse);
const questions = safeParseArray(raw) || [];

const blueprint = prior.blueprint;
const errors = [];

if (questions.length !== blueprint.totalQuestions) {
  errors.push(`Set A returned ${questions.length} questions, expected ${blueprint.totalQuestions}`);
}

questions.forEach((q, i) => {
  if (!q.question || typeof q.question !== 'string' || q.question.trim().length < 5) {
    errors.push(`Set A question ${i + 1} is missing or too short`);
  }
  if (q.marks !== blueprint.marksPerQuestion) {
    errors.push(`Set A question ${i + 1} has incorrect marks`);
  }
  const answerLeakPattern = /\banswer\s*:|\bsolution\s*:/i;
  if (q.question && answerLeakPattern.test(q.question)) {
    errors.push(`Set A question ${i + 1} appears to contain answer/solution text`);
  }
});

const marksSum = questions.reduce((s, q) => s + (Number(q.marks) || 0), 0);
if (marksSum !== blueprint.maximumMarks) {
  errors.push(`Set A total marks (${marksSum}) does not equal Maximum Marks (${blueprint.maximumMarks})`);
}

return [{
  json: {
    examConfig: prior.examConfig,
    blueprint,
    set: { setName: 'Set A', questions },
    setAValidation: { valid: errors.length === 0, errors }
  }
}];

const examConfig = $input.first().json.examConfig;
const blueprint = $input.first().json.blueprint;
const setA = $input.first().json.set;

const distributionText = blueprint.distribution.map(d =>
  `Q${d.questionNumber}: Chapter "${d.chapter}" / Topic "${d.topic}", ` +
  `Marks: ${d.marks}, RBL: ${d.rbl}, CO: ${d.courseOutcomes.join(', ')}`
).join('\n');

const setAQuestionsText = setA.questions.map(q => `- ${q.question}`).join('\n');

const prompt = `You are generating SET B of the same exam paper. Set B must
follow the SAME blueprint (same chapters, topics, marks, RBL, CO per
question number) as Set A below, but every question must be GENUINELY
DIFFERENT from its Set A counterpart.

Blueprint (same structure Set A used):
${distributionText}

Set A questions, for reference ONLY - do not reuse or lightly reword these,
do not just change numbers or names, ask about a different angle or
sub-concept within the same topic instead:
${setAQuestionsText}

Rules:
- Do NOT copy any Set A question.
- Do NOT produce a question that only changes numeric values or names from
  a Set A question.
- Do NOT produce a superficial reword of a Set A question.
- Each Set B question must still match its assigned chapter/topic, be
  clear, answerable, and academically meaningful, and contain no
  answers/solutions.
- Set B must have the same number of questions, same marks, same
  structure, and comparable curriculum coverage and difficulty as Set A.

Return ONLY a JSON array (no prose, no markdown fences) where each item has
exactly this shape:
{
  "questionNumber": number,
  "question": "string",
  "marks": number,
  "rbl": "string",
  "courseOutcomes": ["string"],
  "chapter": "string",
  "topic": "string"
}`;

return [{ json: { examConfig, blueprint, setA, prompt, setName: 'Set B' } }];

const prior = $('Build Prompt - Set B').first().json;
const aiResponse = $input.first().json;

function extractText(resp) {
  // Gemini generateContent response format
  if (resp && Array.isArray(resp.candidates) && resp.candidates.length > 0) {
    const candidate = resp.candidates[0];
    const parts = candidate && candidate.content && candidate.content.parts;
    if (Array.isArray(parts)) {
