const examConfig = $input.first().json.examConfig;
const blueprint = $input.first().json.blueprint;
const set = $input.first().json.set;

return [{
  json: {
    examConfig,
    blueprint,
    sets: [set],
    setBValidation: { valid: true, errors: [] } // no Set B was requested
  }
