const examConfig = $input.first().json.examConfig;
const blueprint = $input.first().json.blueprint;
const sets = $input.first().json.sets;
const setBValidation = $input.first().json.setBValidation;

// Token-overlap (Jaccard) similarity - simple, dependency-free way to
// flag near-duplicate / superficially reworded questions.
function tokenize(text) {
  return new Set(
    String(text || '')
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, ' ')
      .split(/\s+/)
      .filter(t => t.length > 2)
  );
}
function jaccard(a, b) {
  const A = tokenize(a), B = tokenize(b);
  if (A.size === 0 && B.size === 0) return 0;
  const intersection = [...A].filter(t => B.has(t)).length;
  const union = new Set([...A, ...B]).size;
  return union === 0 ? 0 : intersection / union;
}

const SIMILARITY_THRESHOLD = 0.6; // above this = "too similar"
const flags = []; // { setIndex, questionIndex, reason }

if (sets.length === 2) {
  const [setA, setB] = sets;
  setA.questions.forEach((qa, i) => {
    const qb = setB.questions[i];
    if (!qb) return;
    const sim = jaccard(qa.question, qb.question);
    if (sim >= SIMILARITY_THRESHOLD) {
      flags.push({
        setIndex: 1, // flag the Set B question for regeneration
        questionIndex: i,
        reason: `Set B Q${i + 1} is too similar to Set A Q${i + 1} (similarity ${sim.toFixed(2)})`
      });
    }
  });

  // exact duplicate check within each set too
  [setA, setB].forEach((set, setIdx) => {
    for (let i = 0; i < set.questions.length; i++) {
      for (let j = i + 1; j < set.questions.length; j++) {
        const sim = jaccard(set.questions[i].question, set.questions[j].question);
        if (sim >= SIMILARITY_THRESHOLD) {
          flags.push({
            setIndex: setIdx,
            questionIndex: j,
            reason: `${set.setName} Q${j + 1} is too similar to ${set.setName} Q${i + 1} within the same set`
          });
        }
      }
    }
  });
}

return [{
  json: {
    examConfig,
    blueprint,
    sets,
    setBValidation,
    duplicateFlags: flags
  }
}];

const examConfig = $input.first().json.examConfig;
const blueprint = $input.first().json.blueprint;
const sets = $input.first().json.sets;
const duplicateFlags = $input.first().json.duplicateFlags;

const items = duplicateFlags.map(flag => {
  const set = sets[flag.setIndex];
  const q = set.questions[flag.questionIndex];
  const bp = blueprint.distribution[flag.questionIndex];

  const prompt = `Rewrite ONE exam question so it is a genuinely different
question from the one below, while still matching this blueprint slot:

Chapter: ${bp.chapter}
Topic: ${bp.topic}
Marks: ${bp.marks}
RBL: ${bp.rbl}
Course Outcome: ${bp.courseOutcomes.join(', ')}

Question to replace (flagged reason: ${flag.reason}):
"${q.question}"

Rules:
- Do NOT reuse the wording, structure, or numeric setup of the flagged question.
- Ask about a different angle or sub-concept within the same topic.
- Do NOT include answers or solutions.

Return ONLY a JSON object (no prose, no markdown fences) with exactly this
shape:
{ "question": "string" }`;

  return {
    json: {
      examConfig, blueprint, sets, flag, prompt
    }
  };
});

return items;

// IMPORTANT: this node runs in "Run Once for Each Item" mode. Each input
// item here is one AI response for one flagged question. Its own json IS
// the AI response (n8n replaces json with the HTTP Request node's output),
// so the original prompt-builder fields (flag, sets, blueprint, examConfig)
// are fetched back via the paired-item reference to "Build Regeneration
// Prompts", which only resolves correctly in per-item execution mode.

const aiResponse = $input.item.json;
const originalItem = $('Build Regeneration Prompts').item.json;

function extractText(resp) {
  // Gemini generateContent response format
  if (resp && Array.isArray(resp.candidates) && resp.candidates.length > 0) {
    const candidate = resp.candidates[0];
    const parts = candidate && candidate.content && candidate.content.parts;
    if (Array.isArray(parts)) {
      const textPart = parts.find(p => typeof p.text === 'string');
      if (textPart) return textPart.text;
    }
  }
  // Legacy content-array response format (kept for backward compatibility)
  if (resp && Array.isArray(resp.content)) {
    const textBlock = resp.content.find(b => b.type === 'text');
    if (textBlock) return textBlock.text;
  }
  if (typeof resp === 'string') return resp;
  return JSON.stringify(resp);
}
function safeParseObject(text) {
  const cleaned = text.replace(/```json|```/g, '').trim();
  try {
    const parsed = JSON.parse(cleaned);
    return (parsed && typeof parsed === 'object') ? parsed : null;
  } catch (e) {
    return null;
  }
}

const raw = extractText(aiResponse);
const parsed = safeParseObject(raw);

const sets = JSON.parse(JSON.stringify(originalItem.sets)); // deep clone
const flag = originalItem.flag;

if (parsed && parsed.question) {
  sets[flag.setIndex].questions[flag.questionIndex].question = parsed.question;
}

return {
  json: {
    examConfig: originalItem.examConfig,
    blueprint: originalItem.blueprint,
    sets,
    appliedFlag: flag
  }
};

// Collapse the (possibly many) regenerated-question items back into a
// single sets array by applying each item's single question replacement
// on top of the same base sets structure.
const items = $input.all();
if (items.length === 0) {
  return [{ json: { examConfig: {}, blueprint: {}, sets: [] } }];
}

const base = JSON.parse(JSON.stringify(items[0].json.sets));
const examConfig = items[0].json.examConfig;
const blueprint = items[0].json.blueprint;

items.forEach(it => {
  const flag = it.json.appliedFlag;
  const replacedQuestion = it.json.sets[flag.setIndex].questions[flag.questionIndex].question;
  base[flag.setIndex].questions[flag.questionIndex].question = replacedQuestion;
});

return [{ json: { examConfig, blueprint, sets: base } }];

const examConfig = $input.first().json.examConfig;
const blueprint = $input.first().json.blueprint;
const sets = $input.first().json.sets;

const errors = [];

sets.forEach(set => {
  if (set.questions.length !== blueprint.totalQuestions) {
    errors.push(`${set.setName} has ${set.questions.length} questions, expected ${blueprint.totalQuestions}`);
  }
  const marksSum = set.questions.reduce((s, q) => s + (Number(q.marks) || 0), 0);
  if (marksSum !== blueprint.maximumMarks) {
    errors.push(`${set.setName} total marks (${marksSum}) does not equal Maximum Marks (${blueprint.maximumMarks})`);
  }
});

const valid = errors.length === 0;

return [{
  json: {
    success: valid,
    exam: {
      class: examConfig.class,
      section: examConfig.section,
      subject: examConfig.subject,
      examType: examConfig.examType,
      maximumMarks: examConfig.maximumMarks,
      time: examConfig.time,
      totalQuestions: examConfig.totalQuestions,
      questionsToAnswer: examConfig.questionsToAnswer,
      marksPerQuestion: examConfig.marksPerQuestion,
      numberOfSets: examConfig.numberOfSets,
      academicYear: examConfig.academicYear
    },
    blueprint,
    sets,
    error: valid ? undefined : { code: 'FINAL_VALIDATION_FAILED', message: errors.join('; ') }
  }
}];

const j = $input.first().json;
// This is the last node - its output becomes the Execute Workflow result
// returned to 01_EXAM_CONTROLLER.
return [{ json: j }];
